recipes.code:
{
  "inputs": [
    {
      "id": "agent-private-key",
      "type": "promptString",
      "description": "Agent wallet key that auto-pays the $0.05 USDC x402 fee for paid tools. Optional: free tools (get_quote, get_order_status) work without it. Use a dedicated low-balance wallet.",
      "password": true
    }
  ],
  "servers": {
    "fiatdock": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "fiatdock-mcp@1.4.0"
      ],
      "env": {
        "FIATDOCK_URL": "https://fiatdock.com",
        "AGENT_PRIVATE_KEY": "${input:agent-private-key}",
        "FIATDOCK_MAX_PRICE_USD": "<fiatdock-max-price-usd>"
      }
    }
  }
}
